const VIEW = { full: "-200.9 -160.67 1407.5 1407.5", header: "-175.66 -159.77 1357.54 1357.54" };

/**
 * The mark, as the contract reads it. Only the orbit is paced by the turn, so only the orbit's
 * phase is carried across a change. The colours change with the state, which is what survives
 * reduced motion.
 */
const SPEC: MarkSpec = {
  id: "delft",
  beads: 8,
  paced: /^cd-[tnf]$/,
  liveClass: "cm-live",
  look: {
    rest: { "--cd-c0": "oklch(0.38 0.17 266)", "--cd-c1": "oklch(0.38 0.17 266)", "--cd-c2": "oklch(0.38 0.17 266)" },
    live: { "--cd-c0": "oklch(0.8 0.15 75)", "--cd-c1": "oklch(0.62 0.12 160)", "--cd-c2": "oklch(0.47 0.14 320)" },
  },
  turnVar: "--cd-turn",
  paperVar: "--cd-paper",
  view: VIEW,
};

export type DelftMarkProps = MarkProps;

export function DelftMark(props: DelftMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `cd${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "cd-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
